func (_q *CoupleQuery) loadPhotos(ctx context.Context, query *PhotoQuery, nodes []*Couple, init func(*Couple), assign func(*Couple, *Photo)) error {
	query = query.Clone()

	if query.ctx.Limit != nil || query.ctx.Offset != nil {
		limit, offset := -1, 0
		if query.ctx.Limit != nil {
			limit = *query.ctx.Limit
		}
		if query.ctx.Offset != nil {
			offset = *query.ctx.Offset
		}
		query.ctx.Limit, query.ctx.Offset = nil, nil
		query.modifiers = append(query.modifiers, func(selector *sql.Selector) {

			partition := selector.C(couple.PhotosColumn)

			(&sqlgraph.NeighborsLimit{RowNumber: "ent_row_number", DefaultOrderField: photo.FieldID, Offset: offset}).Modifier(partition, limit)(selector)
		})
	}

	fks := make([]driver.Value, 0, len(nodes))
	nodeids := make(map[uuid.UUID]*Couple)
	for i := range nodes {
		fks = append(fks, nodes[i].ID)
		nodeids[nodes[i].ID] = nodes[i]
		if init != nil {
			init(nodes[i])
		}
	}
	if len(query.ctx.Fields) > 0 {
		query.ctx.AppendFieldOnce(photo.FieldCoupleID)
	}
	query.Where(func(s *sql.Selector) {
		s.Where(sql.InValues(s.C(couple.PhotosColumn), fks...))
	})
	neighbors, err := query.All(ctx)
	if err != nil {
		return err
	}
	for _, n := range neighbors {
		fk := n.CoupleID
		node, ok := nodeids[fk]
		if !ok {
			return fmt.Errorf(`unexpected referenced foreign-key "couple_id" returned %v for node %v`, fk, n.ID)
		}
		assign(node, n)
	}
	return nil
}

